create table Student (ID number(10) generated by default as identity, bannercode varchar2(255) not null unique, name varchar2(255) not null, primary key (ID));
create table Scholarship (ID number(10) generated by default as identity, name varchar2(255) not null, type varchar2(255) not null, PdfDocumentID number(10) not null, primary key (ID));
create table Postulation (ID number(10) generated by default as identity, "date" timestamp(0) not null, status varchar2(255) default 'in progress' not null, StudentID number(10) not null, ScholarshipAnnouncementID number(10) not null, primary key (ID));
create table ScholarshipAnnouncement (ID number(10) generated by default as identity, type varchar2(255) not null, startDate timestamp(0) not null, endDate timestamp(0) not null, interviewDate timestamp(0), selectionDate timestamp(0), resultsPublicationDate timestamp(0), ScholarshipID number(10) not null, AcademicPeriodID number(10) not null, primary key (ID));
create table AcademicPeriod (ID number(10) generated by default as identity, period varchar2(255) not null, primary key (ID));
create table Role_Permission (RoleID number(10) not null, PermissionID number(10) not null, primary key (RoleID, PermissionID));
create table Role (ID number(10) generated by default as identity, name varchar2(255) not null, primary key (ID));
create table Permission (ID number(10) generated by default as identity, name varchar2(255) not null, description varchar2(255) not null, primary key (ID));
create table Szacones (PIDM number(10) generated by default as identity, apellidos varchar2(70), nombre varchar2(25), tipo_documento varchar2(25), documento_identidad varchar2(25), codigo_banner varchar2(255) not null unique, telefono varchar2(25), correo_institucional varchar2(70), correo_preferido varchar2(70), programa_inicial varchar2(255), programa_actual_nombre varchar2(25), programa_alterno varchar2(70), beca varchar2(70), tipo_beca varchar2(255), beneficios_beca varchar2(255), requisitos_mantenimiento_beca varchar2(255), estado_programa_beca_filantropia varchar2(25), sexo_registro_nacimiento varchar2(25), identificacion_sexo_nacimiento varchar2(25), genero varchar2(25), orientacion_sexual varchar2(25), nivel_sisben_eps varchar2(70), nombre_madre varchar2(70), nombre_padre varchar2(70), telefono_madre varchar2(25), telefono_padre varchar2(25), contacto_emergencia varchar2(25), parentesco_contacto_emergencia varchar2(25), telefono_contacto_emergencia varchar2(25), discapacidad varchar2(2), tipo_discapacidad varchar2(70), persona_proceso_reincorporacion varchar2(2), persona_victima_conflicto varchar2(2), etnia varchar2(255), lugar_nacimiento varchar2(25), cuidad_procedencia varchar2(25), estrato_procedencia varchar2(25), ciudad_residencia varchar2(25), estrato_residencia varchar2(25), zona_residencia varchar2(25), comuna_residencia varchar2(25), tipo_vivienda varchar2(25), regimen_salud varchar2(25), nivel_educativo_madre varchar2(25), nivel_educativo_padre varchar2(25), medio_transporte varchar2(25), desplaza_otro_municipio varchar2(2), dispositivos_hogar varchar2(255), con_quien_vive varchar2(255), red_apoyo varchar2(255), apoyo_estudios varchar2(25), presiones_externas_estudio varchar2(25), hijos varchar2(2), no_hijos number(2), tiempo_cuidado_hogar varchar2(2), tiene_personas_cargo varchar2(2), icesi_primera_opcion varchar2(25), motivacion_inicial_carrera varchar2(25), areas_mayor_apoyo varchar2(25), examen_ingles number(2), examen_habilidades_basicas varchar2(255), puntaje_pruebas_saber_11 number(3), nivel_matematicas_saber_11 number(1), puntaje_matematicas_saber_11 number(3), nivel_lectura_critica_saber_11 number(1), puntaje_lectura_critica_saber_11 number(3), nivel_ingles_saber_11 varchar2(3), puntaje_ingles_saber_11 number(3), nivel_competencias_ciudadanas_saber_11 number(1), puntaje_competencias_ciudadanas_saber_11 number(1), puntaje_ciencias_naturales_saber_11 number(3), categoria_colegio_egreso varchar2(3), cohorte_programa_principal varchar2(25), cohorte_programa_alterno varchar2(25), estado_actual varchar2(2), nivel_ingles_matriculado varchar2(2), alerta_ingles varchar2(255), semestre number(2), numero_materias_matriculadas number(2), materias_matriculadas varchar2(1000), numero_materias_perdidas number(2), materias_perdidas varchar2(1000), numero_materias_canceladas number(2), materias_canceladas varchar2(255), numero_materias_aprobadas number(3), readmision varchar2(2), promedio_semestre_anterior double precision, promedio_acumulado_prog_principal double precision, promedio_acumulado_prog_alterno double precision, becas varchar2(255), cuadro_honor varchar2(255), motivo_retiro_aplazamiento varchar2(255), notas_parciales varchar2(10000), nitido_rezagado varchar2(25), participacion_actividades_cultura varchar2(25), participacion_actividades_deportes varchar2(255), participacion_actividades_desarrollo_humano varchar2(255), StudentID number(10) not null, primary key (PIDM));
create table Risk (ID number(10) generated by default as identity, risk varchar2(255) not null, "date" timestamp(0) not null, AcademicPeriodID number(10) not null, UserID number(10) not null, StudentID number(10) not null, primary key (ID));
create table "User" (ID number(10) generated by default as identity, name varchar2(255) not null, documentID varchar2(25) not null, primary key (ID));
create table User_Role (UserID number(10) not null, RoleID number(10) not null, primary key (UserID, RoleID));
create table Observation (ID number(10) generated by default as identity, observation varchar2(255) not null, "date" timestamp(0) not null, type varchar2(255) not null, UserID number(10) not null, AcademicPeriodID number(10) not null, StudentID number(10) not null, RiskID number(10), primary key (ID));
create table Psychologist (ID number(10) generated by default as identity, name varchar2(255) not null, documentID varchar2(25), email varchar2(70), phone varchar2(25), primary key (ID));
create table AttendancePsychology (ID number(10) generated by default as identity, "date" timestamp(0) not null, observation varchar2(255), PsychologistID number(10) not null, StudentID number(10) not null, RiskID number(10), primary key (ID));
create table BUActivityType (ID number(10) generated by default as identity, type varchar2(255) not null, primary key (ID));
create table BUActivity (ID number(10) generated by default as identity, name varchar2(255) not null, BUActivityTypeID number(10) not null, primary key (ID));
create table AttendanceBUActivity (ID number(10) generated by default as identity, "date" timestamp(0) not null, observation varchar2(255), BUActivityID number(10) not null, StudentID number(10) not null, ProfessorID number(10) not null, primary key (ID));
create table SupportCenter (ID number(10) generated by default as identity, name varchar2(255) not null unique, primary key (ID));
create table AttendanceSupportCenter (ID number(10) generated by default as identity, "date" timestamp(0) not null, observation varchar2(255), monitorName varchar2(255), SupportCenterID number(10) not null, StudentID number(10) not null, ProfessorID number(10) not null, CourseID number(10) not null, primary key (ID));
create table Donor (ID number(10) generated by default as identity, name varchar2(255) not null, documentType varchar2(10) not null, documentID varchar2(20) not null, primary key (ID));
create table Event (ID number(10) generated by default as identity, name varchar2(255) not null unique, "date" timestamp(0) not null, primary key (ID));
create table Professor (ID number(10) generated by default as identity, name varchar2(255) not null, documentId varchar2(255), email varchar2(70), phone varchar2(25), primary key (ID));
create table PdfDocument (ID number(10) generated by default as identity, fileName number(10) not null unique, uploadDate timestamp(0) not null, primary key (ID));
create table Student_Scholarship (StudentID number(10) not null, ScholarshipID number(10) not null, primary key (StudentID, ScholarshipID));
create table Donor_Event (DonorID number(10) not null, EventID number(10) not null, primary key (DonorID, EventID));
create table Donor_Scholarship (DonorID number(10) not null, ScholarshipID number(10) not null, primary key (DonorID, ScholarshipID));
create table Event_ScholarshipAnnouncement (EventID number(10) not null, ScholarshipAnnouncementID number(10) not null, primary key (EventID, ScholarshipAnnouncementID));
create table Course (ID number(10) generated by default as identity, name varchar2(255) not null, code char(5) unique, department char(3), primary key (ID));
create table Course_Professor (CourseID number(10) not null, ProfessorID number(10) not null, primary key (CourseID, ProfessorID));
create table Dimension (ID number(10) generated by default as identity, dimension varchar2(255) unique, primary key (ID));
create table RiskType (ID number(10) generated by default as identity, DimensionID number(10) not null, riskType varchar2(255) not null, primary key (ID));
create table Risk_RiskType (RiskID number(10) not null, RiskTypeID number(10) not null, riskLevel varchar2(30) check(riskLevel IN ('Low','Medium','High')), primary key (RiskID, RiskTypeID));
